+    #[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
+    enum SuccessorError {
+        #[error("product name `{raw}` is not canonical and safe")]
+        InvalidProductName { raw: String },
+        #[error("coordinated release version `{version}` is not SemVer")]
+        NonSemverProductVersion { version: Version },
+        #[error("coordinated release has no package versions")]
+        EmptyCoordinatedRoster,
+        #[error("coordinated release versions diverge: expected {expected}, found {found}")]
+        DivergentCoordinatedVersion { expected: Version, found: Version },
+        #[error("artifact slot is unsafe")]
+        UnsafeArtifactSlot,
+        #[error("artifact slot provenance is invalid")]
+        InvalidProvenance,
+        #[error("reserved artifact file name is wrong")]
+        WrongReservedFileName,
+        #[error("artifact slot refers to a different product release")]
+        ForeignProductRelease,
+        #[error("package operation does not own its registry slot")]
+        InvalidPackageOperation,
+        #[error("product operation does not own the coordinated product release")]
+        InvalidProductOperation,
+        #[error("release operation prerequisites are invalid")]
+        InvalidPrerequisite,
+        #[error("release operation identities are duplicated")]
+        DuplicateOperation,
+        #[error("artifact slots are duplicated")]
+        DuplicateSlot,
+        #[error("artifact file names are duplicated")]
+        DuplicateFileName,
+        #[error("product artifact roster is not the closed supported set")]
+        InvalidProductRoster,
+        #[error("release operations are not in canonical topological order")]
+        NonCanonicalOperationOrder,
+        #[error("release operation prerequisites contain a cycle")]
+        CyclicPrerequisites,
+        #[error("artifact manifest differs from the intent-bound roster")]
+        MismatchedManifest,
+        #[error("distribution metadata is not canonical")]
+        InvalidMetadata,
+        #[error("checksum roster is not the exact payload plus metadata set")]
+        InvalidChecksumRoster,
+    }
