+            let mut prerequisites = uploads.iter().map(|operation| operation.id.clone()).collect::<Vec<_>>();
+            prerequisites.sort();
+            let mut operations = vec![
+                ReleaseOperation::new(tag.clone(), vec![]).unwrap(),
